CREATE TABLE `family_background` (
  `family_id` int NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `father_edu` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
