  `family_income` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `family_support` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parental_involvement` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fam_rel` int DEFAULT NULL,
  PRIMARY KEY (`family_id`),
  UNIQUE KEY `student_id` (`student_id`),
  CONSTRAINT `family_background_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
