DROP TABLE IF EXISTS `learning_suggestion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learning_suggestion` (
  `suggestion_id` int NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `suggestion_content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `generate_time` datetime NOT NULL,
  `student_feedback` enum('satisfied','neutral','unsatisfied') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suggest_relate_score` int DEFAULT NULL,
  PRIMARY KEY (`suggestion_id`),
  KEY `student_id` (`student_id`),
  CONSTRAINT `learning_suggestion_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

