--
-- Table structure for table `nl2sql_log`
--

DROP TABLE IF EXISTS `nl2sql_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `nl2sql_log` (
  `query_id` int NOT NULL AUTO_INCREMENT,
  `user_id` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `natural_language_input` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `generated_sql` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `execution_time_ms` int DEFAULT NULL,
  `is_correct` tinyint(1) DEFAULT NULL,
  `query_time` datetime NOT NULL,
  PRIMARY KEY (`query_id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `nl2sql_log`
