LOCK TABLES `nl2sql_log` WRITE;
/*!40000 ALTER TABLE `nl2sql_log` DISABLE KEYS */;
INSERT INTO `nl2sql_log` VALUES (1,NULL,'查询所有学生的平均成绩','SELECT \n    AVG(CASE \n        WHEN s.student_id LIKE \'STU_F_%\' THEN es.score \n        ELSE es.score * 5 \n    END) AS 平均成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'',3708,1,'2026-06-03 10:00:30'),(2,NULL,'查询数学成绩前10名的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 数学成绩 FROM student s JOIN exam_score es ON s.student_id = es.student_id WHERE es.subject_id = \'SUBJ_MATH\' AND es.exam_stage = \'G3\' ORDER BY es.score DESC LIMIT 10',946,1,'2026-06-03 10:00:31'),(3,NULL,'查询出勤率低于80%的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, lb.attendance_rate AS 出勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id WHERE lb.attendance_rate < 80',926,1,'2026-06-03 10:00:32'),(4,NULL,'统计各科目的平均分','SELECT \n    sub.subject_name AS 科目,\n    AVG(es.score) AS 平均分\nFROM exam_score es\nJOIN subject sub ON es.subject_id = sub.subject_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY es.subject_id, sub.subject_name',1096,1,'2026-06-03 10:00:33'),(5,NULL,'查询G1到G3成绩持续下滑的学生','SELECT \n    s.student_id AS 学生编号,\n    s.student_name AS 学生姓名,\n    MAX(CASE WHEN es.exam_stage = \'G1\' THEN es.score END) AS G1成绩,\n    MAX(CASE WHEN es.exam_stage = \'G2\' THEN es.score END) AS G2成绩,\n    MAX(CASE WHEN es.exam_stage = \'G3\' THEN es.score END) AS G3成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.subject_id = \'SUBJ_MATH\'\nGROUP BY s.student_id, s.student_name\nHAVING \n    MAX(CASE WHEN es.exam_stage = \'G1\' THEN es.score END) IS NOT NULL\n    AND MAX(CASE WHEN es.exam_stage = \'G2\' THEN es.score END) IS NOT NULL\n    AND MAX(CASE WHEN es.exam_stage = \'G3\' THEN es.score END) IS NOT NULL\n    AND MAX(CASE WHEN es.exam_stage = \'G1\' THEN es.score END) > MAX(CASE WHEN es.exam_stage = \'G2\' THEN es.score END)\n    AND MAX(CASE WHEN es.exam_stage = \'G2\' THEN es.score END) > MAX(CASE WHEN es.exam_stage = \'G3\' THEN es.score END)',2112,1,'2026-06-03 10:00:35'),(6,NULL,'查询高风险预警学生名单','SELECT s.student_id AS 学生编号, s.student_name AS 学生姓名, ra.risk_level AS 风险等级, ra.alert_time AS 预警时间, ra.risk_factors AS 风险因素, ra.intervention_status AS 干预状态 FROM student s JOIN risk_alert ra ON s.student_id = ra.student_id WHERE ra.risk_level = \'high\' ORDER BY ra.alert_time DESC',1100,1,'2026-06-03 10:00:37'),(7,NULL,'统计男女学生的平均成绩差异','SELECT \n    s.student_gender AS 性别,\n    AVG(es.score) AS 平均成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY s.student_gender',1339,1,'2026-06-03 10:00:38'),(8,NULL,'查询学习时长与成绩的关系','SELECT \n    CASE \n        WHEN lb.study_hours < 5 THEN \'少于5小时\'\n        WHEN lb.study_hours BETWEEN 5 AND 10 THEN \'5-10小时\'\n        WHEN lb.study_hours BETWEEN 11 AND 20 THEN \'11-20小时\'\n        ELSE \'20小时以上\'\n    END AS 学习时长区间,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 学生人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY 学习时长区间\nORDER BY 学习时长区间',1606,1,'2026-06-03 10:00:40'),(9,NULL,'查询家庭支持对学生成绩的影响','SELECT \n    fb.family_support AS 家庭支持,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT s.student_id) AS 学生人数\nFROM student s\nJOIN family_background fb ON s.student_id = fb.student_id\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY fb.family_support',1620,1,'2026-06-03 10:00:41'),(10,NULL,'查询缺勤次数最多的10个学生','SELECT s.student_id AS 学生编号, s.student_name AS 学生姓名, (100 - lb.attendance_rate) AS 缺勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id ORDER BY (100 - lb.attendance_rate) DESC LIMIT 10',1161,1,'2026-06-03 10:00:43'),(11,NULL,'查询有额外辅导的学生成绩是否更好','SELECT \n    lb.tutoring_sessions AS 辅导次数,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY lb.tutoring_sessions\nORDER BY lb.tutoring_sessions',1227,1,'2026-06-03 10:00:44'),(12,NULL,'查询有网络接入和没有网络接入的学生成绩对比','SELECT lb.internet_access AS 网络接入, AVG(es.score) AS 平均成绩, COUNT(*) AS 人数 FROM learning_behavior lb JOIN exam_score es ON lb.student_id = es.student_id WHERE es.exam_stage = \'G3\' GROUP BY lb.internet_access',1211,1,'2026-06-03 10:00:45'),(13,NULL,'查询动机水平高的学生平均成绩','SELECT lb.motivation_level AS 动机水平, AVG(es.score) AS 平均成绩 FROM learning_behavior lb JOIN exam_score es ON lb.student_id = es.student_id WHERE lb.motivation_level = \'High\' AND es.exam_stage = \'G3\' GROUP BY lb.motivation_level',1351,1,'2026-06-03 10:00:46'),(14,NULL,'查询年龄和成绩的关系','SELECT \n    s.student_age AS 年龄, \n    AVG(es.score) AS 平均成绩, \n    COUNT(*) AS 人数\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY s.student_age\nORDER BY s.student_age',1412,1,'2026-06-03 10:00:48'),(15,NULL,'查询学校支持对学生成绩的影响','SELECT \n    fb.family_support AS 学校支持,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT es.student_id) AS 学生人数\nFROM \n    family_background fb\nJOIN \n    exam_score es ON fb.student_id = es.student_id\nWHERE \n    es.exam_stage = \'G3\'\nGROUP BY \n    fb.family_support\nORDER BY \n    平均成绩 DESC',1399,1,'2026-06-03 10:00:49'),(16,NULL,'查询各班级的平均成绩排名','SELECT c.class_name AS 班级名称, AVG(es.score) AS 平均成绩 FROM class c JOIN student s ON c.class_id = s.student_class_id JOIN exam_score es ON s.student_id = es.student_id WHERE es.exam_stage = \'G3\' GROUP BY c.class_id, c.class_name ORDER BY 平均成绩 DESC',1939,1,'2026-06-03 10:00:51'),(17,NULL,'查询成绩进步最大的10个学生','SELECT \n    s.student_id AS 学号,\n    s.student_name AS 姓名,\n    g1.score AS 第一次成绩,\n    g3.score AS 第三次成绩,\n    (g3.score - g1.score) AS 进步分数\nFROM student s\nJOIN exam_score g1 ON s.student_id = g1.student_id AND g1.exam_stage = \'G1\'\nJOIN exam_score g3 ON s.student_id = g3.student_id AND g3.exam_stage = \'G3\'\nWHERE g1.subject_id = g3.subject_id\nORDER BY (g3.score - g1.score) DESC\nLIMIT 10',1411,1,'2026-06-03 10:00:53'),(18,NULL,'查询家庭收入水平与学生成绩的关系','SELECT \n    fb.family_income AS 家庭收入水平,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT s.student_id) AS 学生人数\nFROM \n    student s\n    JOIN family_background fb ON s.student_id = fb.student_id\n    JOIN exam_score es ON s.student_id = es.student_id\nWHERE \n    es.exam_stage = \'G3\'\nGROUP BY \n    fb.family_income\nORDER BY \n    FIELD(fb.family_income, \'Low\', \'Medium\', \'High\')',1708,1,'2026-06-03 10:00:55'),(19,NULL,'查询睡眠时间与成绩的关系','SELECT \n    CASE \n        WHEN lb.sleep_hours < 6 THEN \'少于6小时\'\n        WHEN lb.sleep_hours BETWEEN 6 AND 8 THEN \'6-8小时\'\n        WHEN lb.sleep_hours > 8 THEN \'多于8小时\'\n    END AS 睡眠时长区间,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 学生人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY \n    CASE \n        WHEN lb.sleep_hours < 6 THEN \'少于6小时\'\n        WHEN lb.sleep_hours BETWEEN 6 AND 8 THEN \'6-8小时\'\n        WHEN lb.sleep_hours > 8 THEN \'多于8小时\'\n    END\nORDER BY 平均成绩 DESC',1680,1,'2026-06-03 10:00:56'),(20,NULL,'查询参加课外活动和不参加的学生成绩对比','SELECT \n    lb.extracurricular AS 是否参加课外活动, \n    AVG(es.score) AS 平均成绩, \n    COUNT(*) AS 人数 \nFROM learning_behavior lb \nJOIN exam_score es ON lb.student_id = es.student_id \nWHERE es.exam_stage = \'G3\' \nGROUP BY lb.extracurricular',1075,1,'2026-06-03 10:00:57'),(21,NULL,'查询数学成绩前5名的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 成绩 FROM student s JOIN exam_score es ON s.student_id = es.student_id WHERE es.subject_id = \'SUBJ_MATH\' AND es.exam_stage = \'G3\' ORDER BY es.score DESC LIMIT 5',2559,1,'2026-06-03 10:03:19'),(22,NULL,'查询所有学生的平均成绩','SELECT \n    AVG(CASE \n        WHEN s.student_id LIKE \'STU_F_%\' THEN es.score \n        ELSE es.score * 5 \n    END) AS 平均成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'',3329,1,'2026-06-03 10:18:25'),(23,NULL,'查询数学成绩前10名的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 成绩 FROM student s JOIN exam_score es ON s.student_id = es.student_id WHERE es.subject_id = \'SUBJ_MATH\' AND es.exam_stage = \'G3\' ORDER BY es.score DESC LIMIT 10',1023,1,'2026-06-03 10:18:26'),(24,NULL,'查询出勤率低于80%的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, lb.attendance_rate AS 出勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id WHERE lb.attendance_rate < 80',976,1,'2026-06-03 10:18:27'),(25,NULL,'统计各科目的平均分','SELECT \n    sub.subject_name AS 科目, \n    AVG(es.score) AS 平均分 \nFROM exam_score es \nJOIN subject sub ON es.subject_id = sub.subject_id \nWHERE es.exam_stage = \'G3\' \nGROUP BY es.subject_id, sub.subject_name',1124,1,'2026-06-03 10:18:28'),(26,NULL,'查询G1到G3成绩持续下滑的学生','SELECT \n    s.student_id AS 学生编号,\n    s.student_name AS 学生姓名,\n    MAX(CASE WHEN es.exam_stage = \'G1\' THEN es.score END) AS G1成绩,\n    MAX(CASE WHEN es.exam_stage = \'G2\' THEN es.score END) AS G2成绩,\n    MAX(CASE WHEN es.exam_stage = \'G3\' THEN es.score END) AS G3成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.subject_id = \'SUBJ_MATH\'\nGROUP BY s.student_id, s.student_name\nHAVING G1成绩 > G2成绩 AND G2成绩 > G3成绩',1751,1,'2026-06-03 10:18:30'),(27,NULL,'查询高风险预警学生名单','SELECT s.student_id AS 学生编号, s.student_name AS 学生姓名, ra.risk_level AS 风险等级, ra.alert_time AS 预警时间, ra.risk_factors AS 风险因素, ra.intervention_status AS 干预状态 FROM student s JOIN risk_alert ra ON s.student_id = ra.student_id WHERE ra.risk_level = \'high\' ORDER BY ra.alert_time DESC',1042,1,'2026-06-03 10:18:31'),(28,NULL,'统计男女学生的平均成绩差异','SELECT \n    s.student_gender AS 性别,\n    AVG(es.score) AS 平均成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY s.student_gender',954,1,'2026-06-03 10:18:32'),(29,NULL,'查询学习时长与成绩的关系','SELECT \n    CASE \n        WHEN lb.study_hours < 5 THEN \'0-5小时\'\n        WHEN lb.study_hours >= 5 AND lb.study_hours < 10 THEN \'5-10小时\'\n        WHEN lb.study_hours >= 10 AND lb.study_hours < 15 THEN \'10-15小时\'\n        WHEN lb.study_hours >= 15 AND lb.study_hours < 20 THEN \'15-20小时\'\n        ELSE \'20小时以上\'\n    END AS 学习时长区间,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 学生人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY 学习时长区间\nORDER BY 学习时长区间',1715,1,'2026-06-03 10:18:33'),(30,NULL,'查询家庭支持对学生成绩的影响','SELECT \n    fb.family_support AS 家庭支持,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 人数\nFROM family_background fb\nJOIN exam_score es ON fb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY fb.family_support',992,1,'2026-06-03 10:18:34'),(31,NULL,'查询缺勤次数最多的10个学生','SELECT s.student_id AS 学生编号, s.student_name AS 学生姓名, (100 - lb.attendance_rate) AS 缺勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id ORDER BY lb.attendance_rate ASC LIMIT 10',1060,1,'2026-06-03 10:18:36'),(32,NULL,'查询有额外辅导的学生成绩是否更好','SELECT \n    lb.tutoring_sessions AS 辅导次数,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT es.student_id) AS 学生人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY lb.tutoring_sessions\nORDER BY lb.tutoring_sessions',1356,1,'2026-06-03 10:18:37'),(33,NULL,'查询有网络接入和没有网络接入的学生成绩对比','SELECT lb.internet_access AS 网络接入, AVG(es.score) AS 平均成绩, COUNT(*) AS 人数 FROM learning_behavior lb JOIN exam_score es ON lb.student_id = es.student_id WHERE es.exam_stage = \'G3\' GROUP BY lb.internet_access',1341,1,'2026-06-03 10:18:38'),(34,NULL,'查询动机水平高的学生平均成绩','SELECT lb.motivation_level AS 动机水平, AVG(es.score) AS 平均成绩 FROM learning_behavior lb JOIN exam_score es ON lb.student_id = es.student_id WHERE lb.motivation_level = \'High\' AND es.exam_stage = \'G3\' GROUP BY lb.motivation_level',1295,1,'2026-06-03 10:18:40'),(35,NULL,'查询年龄和成绩的关系','SELECT \n    s.student_age AS 年龄, \n    AVG(es.score) AS 平均成绩, \n    COUNT(*) AS 人数\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY s.student_age\nORDER BY s.student_age',1132,1,'2026-06-03 10:18:41'),(36,NULL,'查询学校支持对学生成绩的影响','SELECT \n    fb.family_support AS 学校支持,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT es.student_id) AS 学生人数\nFROM \n    family_background fb\nJOIN \n    exam_score es ON fb.student_id = es.student_id\nWHERE \n    es.exam_stage = \'G3\'\nGROUP BY \n    fb.family_support',1231,1,'2026-06-03 10:18:42'),(37,NULL,'查询各班级的平均成绩排名','SELECT c.class_name AS 班级名称, AVG(es.score) AS 平均成绩 FROM class c JOIN student s ON c.class_id = s.student_class_id JOIN exam_score es ON s.student_id = es.student_id WHERE es.exam_stage = \'G3\' GROUP BY c.class_id, c.class_name ORDER BY 平均成绩 DESC',2561,1,'2026-06-03 10:18:45'),(38,NULL,'查询成绩进步最大的10个学生','SELECT \n    s.student_id AS 学号,\n    s.student_name AS 姓名,\n    g1.score AS 第一次成绩,\n    g3.score AS 第三次成绩,\n    (g3.score - g1.score) AS 进步分数\nFROM student s\nJOIN exam_score g1 ON s.student_id = g1.student_id AND g1.exam_stage = \'G1\'\nJOIN exam_score g3 ON s.student_id = g3.student_id AND g3.exam_stage = \'G3\'\nWHERE g1.subject_id = g3.subject_id\nORDER BY (g3.score - g1.score) DESC\nLIMIT 10',1535,1,'2026-06-03 10:18:46'),(39,NULL,'查询家庭收入水平与学生成绩的关系','SELECT \n    fb.family_income AS 家庭收入水平,\n    AVG(es.score) AS 平均成绩,\n    COUNT(DISTINCT s.student_id) AS 学生人数\nFROM student s\nJOIN family_background fb ON s.student_id = fb.student_id\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY fb.family_income\nORDER BY \n    CASE fb.family_income\n        WHEN \'Low\' THEN 1\n        WHEN \'Medium\' THEN 2\n        WHEN \'High\' THEN 3\n    END',1493,1,'2026-06-03 10:18:48'),(40,NULL,'查询睡眠时间与成绩的关系','SELECT \n    CASE \n        WHEN lb.sleep_hours < 6 THEN \'少于6小时\'\n        WHEN lb.sleep_hours BETWEEN 6 AND 8 THEN \'6-8小时\'\n        WHEN lb.sleep_hours > 8 THEN \'多于8小时\'\n    END AS 睡眠时长区间,\n    AVG(es.score) AS 平均成绩,\n    COUNT(*) AS 学生人数\nFROM learning_behavior lb\nJOIN exam_score es ON lb.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY \n    CASE \n        WHEN lb.sleep_hours < 6 THEN \'少于6小时\'\n        WHEN lb.sleep_hours BETWEEN 6 AND 8 THEN \'6-8小时\'\n        WHEN lb.sleep_hours > 8 THEN \'多于8小时\'\n    END\nORDER BY 平均成绩 DESC',1790,1,'2026-06-03 10:18:50'),(41,NULL,'查询参加课外活动和不参加的学生成绩对比','SELECT \n    lb.extracurricular AS 是否参加课外活动, \n    AVG(es.score) AS 平均成绩, \n    COUNT(*) AS 人数 \nFROM learning_behavior lb \nJOIN exam_score es ON lb.student_id = es.student_id \nWHERE es.exam_stage = \'G3\' \nGROUP BY lb.extracurricular',1152,1,'2026-06-03 10:18:51'),(42,NULL,'统计各科目的平均分','SELECT \n    sub.subject_name AS 科目,\n    AVG(es.score) AS 平均分\nFROM exam_score es\nJOIN subject sub ON es.subject_id = sub.subject_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY es.subject_id, sub.subject_name',2401,1,'2026-06-03 10:19:32'),(43,NULL,'统计男女学生的平均成绩差异','SELECT \n    s.student_gender AS 性别,\n    AVG(es.score) AS 平均成绩\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nWHERE es.exam_stage = \'G3\'\nGROUP BY s.student_gender',1884,1,'2026-06-04 01:07:05'),(44,NULL,'???????????','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 成绩, sub.subject_name AS 科目\nFROM student s\nJOIN exam_score es ON s.student_id = es.student_id\nJOIN subject sub ON es.subject_id = sub.subject_id\nWHERE es.exam_stage = \'G3\'\n  AND (\n    (s.student_id LIKE \'STU_M_%\' AND es.score >= 10)\n    OR\n    (s.student_id LIKE \'STU_P_%\' AND es.score >= 10)\n    OR\n    (s.student_id LIKE \'STU_F_%\' AND es.score >= 60)\n  )\nORDER BY es.score DESC',2263,1,'2026-06-04 01:12:08'),(45,NULL,'?????????','抱歉，我无法理解您的问题。请用中文描述您想要查询的内容。',0,0,'2026-06-04 01:12:51'),(46,NULL,'???????10????','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 成绩 \nFROM student s \nJOIN exam_score es ON s.student_id = es.student_id \nWHERE es.subject_id = \'SUBJ_MATH\' \n  AND es.exam_stage = \'G3\' \nORDER BY es.score DESC \nLIMIT 10',1193,1,'2026-06-04 01:13:05'),(47,NULL,'???????80%???','SELECT s.student_id AS 学号, s.student_name AS 姓名, lb.attendance_rate AS 出勤率\nFROM student s\nJOIN learning_behavior lb ON s.student_id = lb.student_id\nWHERE lb.attendance_rate < 80',1042,1,'2026-06-04 01:14:45'),(48,NULL,'查询数学成绩前10名的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, es.score AS 成绩 FROM student s JOIN exam_score es ON s.student_id = es.student_id WHERE es.subject_id = \'SUBJ_MATH\' AND es.exam_stage = \'G3\' ORDER BY es.score DESC LIMIT 10',5349,1,'2026-06-06 14:59:53'),(49,NULL,'查询缺勤次数最多的10个学生','SELECT s.student_id AS 学生编号, s.student_name AS 学生姓名, (100 - lb.attendance_rate) AS 缺勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id ORDER BY (100 - lb.attendance_rate) DESC LIMIT 10',2551,1,'2026-06-06 19:49:29'),(50,NULL,'查询各班级的平均成绩排名','SELECT c.class_name AS 班级名称, AVG(es.score) AS 平均成绩 FROM class c JOIN student s ON c.class_id = s.student_class_id JOIN exam_score es ON s.student_id = es.student_id WHERE es.exam_stage = \'G3\' GROUP BY c.class_id, c.class_name ORDER BY 平均成绩 DESC',2674,1,'2026-06-06 20:20:50'),(51,NULL,'查询出勤率低于80%的学生','SELECT s.student_id AS 学号, s.student_name AS 姓名, lb.attendance_rate AS 出勤率 FROM student s JOIN learning_behavior lb ON s.student_id = lb.student_id WHERE lb.attendance_rate < 80',18016,1,'2026-06-08 23:00:47');
