DROP TABLE IF EXISTS `risk_alert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `risk_alert` (
  `alert_id` int NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `risk_level` enum('low','medium','high') COLLATE utf8mb4_unicode_ci NOT NULL,
  `alert_time` datetime NOT NULL,
  `risk_factors` text COLLATE utf8mb4_unicode_ci,
  `intervention_status` enum('pending','in_progress','completed') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `intervention_measure` text COLLATE utf8mb4_unicode_ci,
  `intervention_result` text COLLATE utf8mb4_unicode_ci,
  `risk_score` int DEFAULT '0',
  PRIMARY KEY (`alert_id`),
  KEY `student_id` (`student_id`),
  CONSTRAINT `risk_alert_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30621 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

